  ui_story_5023_50230101_79_dialog_content = "Depois disso, Acer e eu corremos de um lugar para outro com a ajuda do dinheiro Azure deu-me.",
  ui_story_5023_50230101_80_dialog_content = "Não muito tempo depois, a conspiração da Blue Lion Guild foi exposta. O Senhor das Sombras lidou com eles, e finalmente ficamos livres de nossos perseguidores.",
  ui_story_5023_50230101_81_dialog_content = "Eu perguntei sobre a senhorita Azure tudo e aprendi sobre um monte de feitos heróicos que ela realizou, o que me levou a querer entrar para a Rediesel Wrench.",
