  ui_story_5023_50230101_109_dialog_content = "Depois de dominar todos os seus drinks especiais, venha abrir uma taverna em nosso Oasis.",
  ui_story_5023_50230101_110_dialog_content = "Beleza!",
  ui_story_5023_50230101_111_dialog_content = "Você está realmente indo a extremos para conseguir bebidas grátis...",
  ui_story_5023_50230101_112_dialog_content = "Estou com tanta fome de repente. O que tem para o jantar?",
  ui_story_5023_50230101_113_dialog_content = "Essa foi uma mudança muito ruim de assunto.",
  ui_story_5023_50230101_114_dialog_content = "... Eu fiz camelo cozido no vapor com cebola do deserto.",
  ui_story_5023_50230201_1_dialog_content = "...",
  ui_story_5023_50230201_2_dialog_content = "... Excelente. Ele não está por perto. Agora é a hora.",
  ui_story_5023_50230201_3_dialog_content = "Azure?",
