  ui_story_5023_50230201_7_dialog_content = "Nunca mais ganharei uma discussão contra ele se descobrir que me machuquei durante uma emboscada.",
  ui_story_5023_50230201_8_dialog_content = "Então você está... tentando roubar suprimentos de primeiros socorros? Vou ajudá-lo a tratar suas feridas.",
  ui_story_5023_50230201_9_dialog_content = "Não, são apenas ferimentos superficiais. Além disso, você está saindo com Sinsa, não é?",
