  ui_story_5023_50230201_11_dialog_content = "... Negócio.",
  ui_story_5023_50230201_12_dialog_content = "Bem, não é tão ruim quanto parece. A maior parte do sangue não é seu, então você deve ficar bem.",
  ui_story_5023_50230201_13_dialog_content = "Sinto que não recebo tanto cuidado ou atenção de você nos dias de hoje. Não me ama mais?",
  ui_story_5023_50230201_14_dialog_content = "Por acaso você bateu a cabeça? Porque parece que sim. Talvez eu devesse ligar Roy para dar uma olhada.",
  ui_story_5023_50230201_15_dialog_content = "Eu estava brincando. Foi uma piada!",
  ui_story_5023_50230201_16_dialog_content = "Isso provavelmente vai doer um pouco. Tenha paciencia comigo.",
  ui_story_5023_50230201_17_dialog_content = "É raro você cair na armadilha de alguém.",
  ui_story_5023_50230201_18_dialog_content = "Você deveria ter visto como meus oponentes acabaram.",
  ui_story_5023_50230201_19_dialog_content = "Eu acredito que os abutres devem estar se alimentando dos restos daqueles pirralhos humildes agora.",
  ui_story_5023_50230201_20_dialog_content = "O líder do grupo alegou ser o sobrevivente de uma gangue que o Rediesel Wrench havia eliminado no passado.",
  ui_story_5023_50230201_21_dialog_content = "Qual gangue?",
  ui_story_5023_50230201_22_dialog_content = "Eu fiz a mesma pergunta.",
