  ui_story_5023_50230201_29_dialog_content = "Eu vejo. É a única coisa que você investigaria mesmo sabendo que poderia ser uma armadilha.",
  ui_story_5023_50230201_30_dialog_content = "Não há nenhum risco que eu não esteja disposto a correr se houver uma chance de me levar ao meu irmão.",
  ui_story_5023_50230201_31_dialog_content = "Você não deveria estar trazendo alguém com você em momentos como esses?",
  ui_story_5023_50230201_32_dialog_content = "Ai. Vá com calma, sim?",
  ui_story_5023_50230201_33_dialog_content = "Suas habilidades de enfermagem não melhoraram em nada.",
  ui_story_5023_50230201_34_dialog_content = "Você sabe que eu não me machuco com frequência, assim como você. Raramente tenho a oportunidade de praticar.",
  ui_story_5023_50230201_35_dialog_content = "O que é bom, diga-se de passagem.",
  ui_story_5023_50230201_36_dialog_content = "Tudo bem, eu terminei.",
  ui_story_5023_50230201_37_dialog_content = "Aqui você vai. Algumas coisas boas de Jomu. Eu tenho guardado apenas para você. Com gelo?",
  ui_story_5023_50230201_38_dialog_content = "Hum... lindo!",
  ui_story_5023_50230201_39_dialog_content = "E sentado aqui, você tem uma vista panorâmica do Oasis. Eu amo isso.",
  ui_story_5023_50230201_40_dialog_content = "Seu ombro é tão confortável para se apoiar.",
  ui_story_5023_50230201_41_dialog_content = "...",
  ui_story_5023_50230201_42_dialog_content = "Eu tenho que viver, mesmo que apenas para esses momentos. Para sobreviver, e voltar.",
  ui_story_5023_50230201_43_dialog_content = "Desde que você saiba disso.",
  ui_story_5023_50230201_44_dialog_content = "Vamos beber para o conteúdo do nosso coração hoje!",
  ui_story_5023_50230201_45_dialog_content = "Hum... com prazer.",
  ui_story_5023_50230301_1_dialog_content = "As equipes estão prontas, ingredientes e prêmios... confirmados.",
  ui_story_5023_50230301_2_dialog_content = "Formidável. Nós finalmente temos algo além do Insect Protein Powder da Jomu e bonecas aleatórias este ano como prêmios.",
  ui_story_5023_50230301_3_dialog_content = "eu me pergunto onde Jomu é...",
  ui_story_5023_50230301_4_dialog_content = "Tiny One prendê-lo por ocupar muito espaço no armazém, ele provavelmente está implorando por misericórdia agora.",
  ui_story_5023_50230301_5_dialog_content = "Odi, você voltou! Os pontos de comunicação para todas as etapas estão definidos?",
  ui_story_5023_50230301_6_dialog_content = "É claro. Pedaco de bolo.",
  ui_story_5023_50230301_7_dialog_content = "Você tem ideia de quantas falhas técnicas estúpidas eu tenho que lidar com todos esses idiotas todos os dias?",
  ui_story_5023_50230301_8_dialog_content = "Mais da metade de seus problemas são sempre corrigidos apenas reiniciando! Francamente, são seus cérebros que precisam de manutenção—",
  ui_story_5023_50230301_9_dialog_content = "Err... me desculpe. falei demais.",
  ui_story_5023_50230301_10_dialog_content = "Você é provavelmente o único mais ocupado do que eu em toda Rediesel Wrench.",
  ui_story_5023_50230301_11_dialog_content = "Quando Tiny One, Fleur e todos nós temos nossas mãos ocupadas, você é sempre aquele a quem pedimos ajuda...",
  ui_story_5023_50230301_12_dialog_content = "Haha, não sou profissional. Considero um milagre não acabar causando mais problemas.",
  ui_story_5023_50230301_13_dialog_content = "Aí está você, Roy! A manutenção e os testes do Lepidoz estão concluídos.",
  ui_story_5023_50230301_14_dialog_content = "Com tanto rediesel na barriga, Lepidoz deve conseguir acompanhar nossos competidores até o final da corrida sem nenhum problema.",
  ui_story_5023_50230301_15_dialog_content = "Quão útil Odi também está aqui! Temos algumas coisas para verificar com você sobre as configurações de comunicação de rádio do Lepidoz...",
  ui_story_5023_50230301_16_dialog_content = "Roy!",
  ui_story_5023_50230301_17_dialog_content = "Qual é o problema, Líder?",
  ui_story_5023_50230301_17X_dialog_content = "Uau!",
  ui_story_5023_50230301_18_dialog_content = "Você pode impedir Zeta de adicionar tantos detalhes estranhos à minha persona?!",
  ui_story_5023_50230301_19_dialog_content = "Eu não me importo de ser um berserker, mas por que eu tenho que ser \"três vezes divorciado\"?",
  ui_story_5023_50230301_20_dialog_content = "Er, recue um pouco primeiro, sim? Nós dois velhos de pé com nossos rostos tão próximos vamos causar uma cena.",
  ui_story_5023_50230301_21_dialog_content = "Eu não sou um homem velho!",
  ui_story_5023_50230301_22_dialog_content = "Claro, claro, espere mais alguns anos.",
  ui_story_5023_50230301_23_dialog_content = "De qualquer forma, parece que você está bem interpretando Zeta, mas não está feliz com seu papel.",
  ui_story_5023_50230301_24_dialog_content = "Nem todos gostamos de responder a tudo o que Zeta nos chama, ao contrário de algumas pessoas... Princesa.",
  ui_story_5023_50230301_25_dialog_content = "Não me entenda mal! Acho o papel de princesa muito desafiador. Definitivamente um dos três principais personagens difíceis de interpretar.",
  ui_story_5023_50230301_26_dialog_content = "Se você pudesse mudar sua personalidade, o que você escolheria? Não me diga que você usaria Shinnosuke...",
  ui_story_5023_50230301_27_dialog_content = "Eu ainda não usei essas histórias como contos de ninar para as crianças ainda.",
  ui_story_5023_50230301_28_dialog_content = "Zeta é facilmente influenciado. Se eu fizer isso, não demorará muito para ela mudar seu papel para um viajante errante do Extremo Oriente empunhando uma lâmina demoníaca.",
  ui_story_5023_50230301_29_dialog_content = "... Você já leu essa série também?",
  ui_story_5023_50230301_30_dialog_content = "Você está brincando? Todas as fortalezas sabem.",
  ui_story_5023_50230301_31_dialog_content = "Você parece ter comprado um monte de cópias para enviar para as pessoas, então obsessivamente foi atrás delas perguntando sobre seus personagens favoritos.",
  ui_story_5023_50230301_32_dialog_content = "Isso mesmo, mas você me faz parecer tão...",
  ui_story_5023_50230301_33_dialog_content = "\"Eu vou matar mil vilões neste mundo para manter minha irmã segura pelo resto de sua vida!\"",
  ui_story_5023_50230301_34_dialog_content = "Você não precisa gritar!",
  ui_story_5023_50230301_35_dialog_content = "O que há para se envergonhar? Não se esqueça que eu li toda a poesia que você escreveu quando criança. Esses foram ainda mais...",
  ui_story_5023_50230301_36_dialog_content = "A propósito, eu estava limpando o armazém outro dia e encontrei mais algumas daquelas coleções de poesia.",
  ui_story_5023_50230301_37_dialog_content = "O quê?!",
  ui_story_5023_50230301_38_dialog_content = "Não se atreva a mostrá-los para Azure! Você não tem ideia de quanto tempo ela me provocou sobre isso depois!",
  ui_story_5023_50230301_39_dialog_content = "Ahahah. Depois de todos esses anos, você ainda não sabe como lidar com ela.",
  ui_story_5023_50230301_40_dialog_content = "Hum...",
  ui_story_5023_50230301_41_dialog_content = "Esta é uma oportunidade extremamente rara. Você quer se juntar a Azure para o rali este ano?",
  ui_story_5023_50230301_42_dialog_content = "Às vezes eu realmente não posso dizer se você está brincando ou não... é isso que você chama de terapia de exposição?",
  ui_story_5023_50230301_43_dialog_content = "Mas além Azure, quem mais é mais adequado para mostrar PlayerName as técnicas de corrida da Rediesel Wrench?",
  ui_story_5023_50230301_44_dialog_content = "... Você tem razão.",
  ui_story_5023_50230301_45_dialog_content = "Mas primeiro, dê-me aquelas coleções de poesia que você encontrou.",
  ui_story_5023_50230301_46_dialog_content = "Hmm... O que devo fazer?",
  ui_story_5023_50230301_47_dialog_content = "Você sabe como as coisas funcionam em Rediesel Wrench: primeiro a chegar, primeiro a servir, localizadores, goleiros.",
  ui_story_5023_50230301_48_dialog_content = "A menos, é claro, que você esteja me ordenando como meu líder... ou se você puder tirá-los de mim à força...",
  ui_story_5023_50230301_49_dialog_content = "... Eu não vou me segurar então!",
  ui_story_5023_50230301_50_dialog_content = "Uau... que assustador.",
  ui_story_5023_50230301_51_dialog_content = "Não é PlayerName Esperando Por Você? Não é legal deixar o convidado esperando.",
  ui_story_5023_50230301_52_dialog_content = "É tarde demais para retirar suas palavras, Roy.",
  ui_story_5023_50230301_53_dialog_content = "Mude minha ideia? Nunca! Você tem um minuto. Pegue este bloco de notas de mim e os poemas serão seus.",
  ui_story_5023_50230301_54_dialog_content = "Caso contrário, considere seriamente entrar na corrida com Azure.",
  ui_story_5023_50230301_55_dialog_content = "Ela está tão farta da minha irritação. Um de vocês pode chegar até ela...",
  ui_story_5023_50230301_56_dialog_content = "Você disse alguma coisa?",
  ui_story_5023_50230301_57_dialog_content = "Ahhh... Nada.",
  ui_story_5023_50230301_58_dialog_content = "Você tem 50 segundos restantes, Líder.",
  ui_story_5023_50230301_59_dialog_content = "Isso é batota!",
  ui_story_5023_50230301_60_dialog_content = "Ai... Meu corpo todo dói... Tiny One é implacável...",
  ui_story_5023_50230301_61_dialog_content = "Hum? Uma luta?",
  ui_story_5023_50230301_62_dialog_content = "Uau! Ele se esquivou da chave inglesa do chefe e decolou tão rápido!",
  ui_story_5023_50230301_63_dialog_content = "Roy definitivamente não é alguém com quem você quer mexer ... O que aconteceu com eles de qualquer maneira?",
  ui_story_5023_50230301_64_dialog_content = "Huh? Eu não estava prestando atenção. É melhor você cuidar da sua cabeça inchada antes de começar a se meter nos negócios dos outros. Realmente, você nunca aprende a lição.",
  ui_story_5023_50230301_65_dialog_content = "Eu ouvi Zeta. E algo sobre pegar um bloco de notas em um minuto. ...É isso.",
  ui_story_5023_50230301_66_dialog_content = "Estou disposto a apostar um kit de ferramentas que em uma batalha de habilidade em vez de resistência, Boss não tem chance.",
  ui_story_5023_50230301_67_dialog_content = "Estou fora. Eu não sou idiota.",
  ui_story_5023_50230301_68_dialog_content = "Hum. Tenho uma boa manchete para o Umbraton Daily.",
  ui_story_5023_50230301_69_dialog_content = "\"Conflito entre o Líder da Chave Rediesel e o Membro Sênior sobre o Treinamento de Novos Talentos!\"",
  ui_story_5023_50230301_70_dialog_content = "Eu me pergunto quanto as pessoas de Nightium pagariam para ler isso...",
  ui_story_5023_50230401_1_dialog_content = "Realmente não há outra opção?",
  ui_story_5023_50230401_2_dialog_content = "Vamos, confie em mim. Red Scorpion Pie é excelente.",
  ui_story_5023_50230401_3_dialog_content = "Como você é um VIP, o chef o tornou especial só para você. O seu não tem apenas Deep Fried Flare Scorpion, ele também inclui um bônus Roasted Crimson Ring Snake.",
  ui_story_5023_50230401_4_dialog_content = "Isso é para ser um incentivo?",
  ui_story_5023_50230401_5_dialog_content = "Ambos soam mortais para mim!",
  ui_story_5023_50230401_6_dialog_content = "Não tenha medo! Tire a cabeça e o bumbum e divirta-se!",
  ui_story_5023_50230401_7_dialog_content = "Os mais aptos sobrevivem. A regra mais forte. É assim que funciona a vida no deserto.",
  ui_story_5023_50230401_8_dialog_content = "Você consome esta torta com respeito pelas vidas das criaturas derrotadas usadas para fazê-la, suas vidas se tornam parte de sua carne e sangue, e assim a vida continua.",
  ui_story_5023_50230401_9_dialog_content = "Seu discurso é muito poético e contundente, mas eu...",
  ui_story_5023_50230401_10_dialog_content = "Jovem, que tal uma sopa de aperitivo?",
  ui_story_5023_50230401_11_dialog_content = "Obrigada!",
  ui_story_5023_50230401_12_dialog_content = "*Tosse*... O que diabos é isso?",
  ui_story_5023_50230401_13_dialog_content = "Sopa de verme da areia e gafanhoto!",
  ui_story_5023_50230401_14_dialog_content = "Uau, que nome brutalmente direto.",
  ui_story_5023_50230401_15_dialog_content = "Espere, eu já ouvi isso antes... estava em um livro?",
  ui_story_5023_50230401_16_dialog_content = "Ha, você é muito culto!",
  ui_story_5023_50230401_17_dialog_content = "Esta é uma famosa iguaria do deserto. Aparentemente, alguns chefs de outras regiões tentaram reproduzi-lo mesmo quando não conseguiam colocar as mãos em todos os ingredientes essenciais.",
  ui_story_5023_50230401_18_dialog_content = "\"Adicione páprica defumada e gafanhotos fritos. Cubra com uma colher de sopa de molho de pimenta...\"",
  ui_story_5023_50230401_19_dialog_content = "Por acaso você serve Arroz de Arenito?",
  ui_story_5023_50230401_20_dialog_content = "Como você conhece o prato especial do proprietário? Não está nem no cardápio!",
  ui_story_5023_50230401_21_dialog_content = "Acho que ele deve gostar muito da nossa cozinha do deserto. Dê-lhe outra garrafa de leite de camelo.",
  ui_story_5023_50230401_22_dialog_content = "Este restaurante é propriedade do tio Johnny?",
  ui_story_5023_50230401_23_dialog_content = "Ohh? Você também viu a Receita Rediesel?",
  ui_story_5023_50230401_24_dialog_content = "Você não pode estar falando sério!",
  ui_story_5023_50230401_25_dialog_content = "Estou querendo conhecê-lo desde que li seu livro...",
  ui_story_5023_50230401_26_dialog_content = "Por que você não disse algo antes? Johnny está atualmente viajando pelo mundo em busca de novas inspirações.",
  ui_story_5023_50230401_27_dialog_content = "Ele não vai voltar para o Blazing Rally.",
  ui_story_5023_50230401_28_dialog_content = "Johnny é um dos poucos membros aqui que não gosta de corridas.",
  ui_story_5023_50230401_29_dialog_content = "Seu coração e alma estão cheios de comida.",
  ui_story_5023_50230401_30_dialog_content = "Aposto que ele está atualmente em uma emboscada do lado de fora de um covil de Eclipsite, em busca de saborosos Eclipsites.",
  ui_story_5023_50230401_31_dialog_content = "Eclipsitos são comestíveis?!",
  ui_story_5023_50230401_32_dialog_content = "Agora que penso nisso, ele afirmou ser um provador de carne Eclipsite em seu livro...",
  ui_story_5023_50230401_33_dialog_content = "É uma pena que você não possa conhecê-lo desta vez. Mas a comida vai... o que foi mesmo?",
  ui_story_5023_50230401_34_dialog_content = "Ah, certo. A comida conectará vocês dois além do tempo e do espaço.",
  ui_story_5023_50230401_35_dialog_content = "A propósito, eu não tirei isso da minha bunda. É o que Johnny sempre diz.",
  ui_story_5023_50230401_36_dialog_content = "Ele tem planos de imprimi-lo na capa de sua sequência Rediesel Recipe.",
  ui_story_5023_50230401_37_dialog_content = "(Vice também adora experimentar ingredientes incomuns... mas seus pratos são mais como armas letais do que comida de verdade.)",
  ui_story_5023_50230401_38_dialog_content = "(Mas esta é a minha oportunidade de experimentar todas as coisas excitantes do livro!)",
  ui_story_5023_50230401_39_dialog_content = "(Pior cenário, minha viagem termina com uma intoxicação alimentar na noite anterior à corrida...)",
  ui_story_5023_50230401_40_dialog_content = "Ok! Eu irei comer!",
  ui_story_5023_50230401_41_dialog_content = "...",
  ui_story_5023_50230401_42_dialog_content = "(Ah! De alguma forma, eu ainda estou vivo. E...)",
  ui_story_5023_50230401_43_dialog_content = "... Isso ... tem um gosto muito bom.",
  ui_story_5023_50230401_44_dialog_content = "Sim! Você gosta disso!",
  ui_story_5023_50230401_45_dialog_content = "Sim. O escorpião é tão crocante por fora e muito macio e suculento por dentro. E o tempero picante e azedo é de morrer...",
  ui_story_5023_50230401_46_dialog_content = "... Ouça essas palavras chiques! Você consegue tudo isso dos livros que lê?",
  ui_story_5023_50230401_47_dialog_content = "Eu sei direito? Ao contrário de nós. Só somos bons em encher a cara e dizer: \"Droga, isso é bom!\"",
  ui_story_5023_50230401_48_dialog_content = "Suspirar. Eu gostaria que Johnny pudesse ouvir isso por si mesmo.",
  ui_story_5023_50230401_49_dialog_content = "... PlayerName.",
  ui_story_5023_50230401_50_dialog_content = "Sim?",
  ui_story_5023_50230401_51_dialog_content = "Você estaria interessado em experimentar e rever tudo o que o restaurante tem? Isso realmente faria Johnny feliz.",
  ui_story_5023_50230401_52_dialog_content = "Err... sugiro que guardemos alguns para a próxima vez. Minhas papilas gustativas estão no limite do dia...",
  ui_story_5023_50230401_53_dialog_content = "A festa comemorativa acontecerá no final da corrida. Você não será capaz de obter quaisquer segundos lá.",
  ui_story_5023_50230401_54_dialog_content = "É mesmo?",
  ui_story_5023_50230401_55_dialog_content = "(Estou um pouco desapontado, mas também um pouco aliviado...)",
  ui_story_5023_50230401_56_dialog_content = "Ei, não se preocupe! Roy está a cargo da festa de celebração.",
  ui_story_5023_50230401_57_dialog_content = "Será outra aventura emocionante para o seu paladar, quase tão emocionante quanto os pratos do Johnny!",
  ui_story_5023_50230401_58_dialog_content = "Comer é sempre uma aventura com Rediesel Wrench?",
  ui_story_5023_50230401_59_dialog_content = "Tudo bem, você deve estar com sede depois de toda essa conversa.",
  ui_story_5023_50230401_60_dialog_content = "Beba o suco de fruta podre da língua deste dragão e em seguida vamos experimentar o menu secreto!",
  ui_story_5023_50230401_61_dialog_content = "Hum... Incluindo arroz de arenito?",
  ui_story_5023_50230401_62_dialog_content = "(Vai ser uma longa noite...)",
  ui_story_5023_50230501_1_dialog_content = "Hmm... eu... eu não consigo ver o que vem pela frente...",
  ui_story_5023_50230501_2_dialog_content = "Essa voz... Zeta? Para que servem todas essas roupas?",
  ui_story_5023_50230501_3_dialog_content = "Uau!",
  ui_story_5023_50230501_4_dialog_content = "Devo pegá-los rapidamente.",
  ui_story_5023_50230501_5_dialog_content = "Emm... Zeta está lavando roupa!",
  ui_story_5023_50230501_6_dialog_content = "Todos esses são meus!",
  ui_story_5023_50230501_7_dialog_content = "Jona, você viu as roupas e o chapéu que eu tinha pendurado lá fora?",
  ui_story_5023_50230501_8_dialog_content = "Não.",
  ui_story_5023_50230501_9_dialog_content = "Espere... Eu vi Zeta com um monte de roupas mais cedo. Ela pode ter pego o seu por acidente.",
  ui_story_5023_50230501_10_dialog_content = "Como, quando ela tem metade do meu tamanho?",
  ui_story_5023_50230501_11_dialog_content = "Eu não sei sobre isso. Alguns de seus tops são bem curtos. Ame-os, aliás.",
  ui_story_5023_50230501_12_dialog_content = "Heh... Por mais que eu queira ficar e ouvir seus elogios, eu realmente tenho que encontrar Zeta.",
  ui_story_5023_50230501_13_dialog_content = "Vá em frente. Não é como se eu estivesse com ciúmes ou algo assim.",
  ui_story_5023_50230501_14_dialog_content = "Ugh... isso... deveria ser assim? Qualquer que seja!",
  ui_story_5023_50230501_15_dialog_content = "Ah! O-Oh não! Até eu posso dizer que não está certo...",
  ui_story_5023_50230501_16_dialog_content = "Talvez eu limpe? ...Está ainda pior agora!",
  ui_story_5023_50230501_17_dialog_content = "De acordo com Barbara, fazer maquiagem é como desenhar, mas por que...",
  ui_story_5023_50230501_18_dialog_content = "Você realmente tem que perguntar? Você esqueceu o quão terrível você é no desenho?",
  ui_story_5023_50230501_19_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_5023_50230501_20_dialog_content = "A-Azure? O que te traz aqui?!",
  ui_story_5023_50230501_21_dialog_content = "Pare aí mesmo. Esta é a base secreta da heroína. Se o lacaio do diabo força sua entrada—",
  ui_story_5023_50230501_22_dialog_content = "<size=45>Me deixe terminar!</size>",
  ui_story_5023_50230501_23_dialog_content = "Hum? Você não deveria olhar alguém nos olhos quando fala com eles?",
  ui_story_5023_50230501_24_dialog_content = "Um... u-uh... Aham! *tosse* Estou resfriado e não quero passar para você...",
  ui_story_5023_50230501_25_dialog_content = "Oh meu Deus, uma doença súbita, hein? Não me venha com isso, idiota, não fique doente.",
  ui_story_5023_50230501_26_dialog_content = "Vire-se para mim.",
  ui_story_5023_50230501_27_dialog_content = "<size=45>H-Espere! Você pode prometer que não vai rir?</size>",
  ui_story_5023_50230501_28_dialog_content = "Você sabe como é difícil me fazer rir.",
  ui_story_5023_50230501_29_dialog_content = "...",
  ui_story_5023_50230501_30_dialog_content = "Pfft...",
  ui_story_5023_50230501_31_dialog_content = "Você prometeu que não iria rir!",
  ui_story_5023_50230501_32_dialog_content = "Sinto muito, ó grande heroína.",
  ui_story_5023_50230501_33_dialog_content = "Eu esperava que fosse divertido, mas isso supera todas as minhas expectativas. Como alguém pode não rir disso?",
  ui_story_5023_50230501_34_dialog_content = "Você!",
  ui_story_5023_50230501_35_dialog_content = "Venha. Limpe seu rosto com esta toalha.",
  ui_story_5023_50230501_36_dialog_content = "...",
  ui_story_5023_50230501_37_dialog_content = "Então me diga o que está acontecendo, por que de repente você está interessado em maquiagem?",
  ui_story_5023_50230501_38_dialog_content = "...N-Nenhuma razão!",
  ui_story_5023_50230501_39_dialog_content = "Bem... Veja, Barbara me disse que isso funcionaria como um amuleto mágico que aumentaria o poder da heroína!",
  ui_story_5023_50230501_40_dialog_content = "Sim! É isso!",
  ui_story_5023_50230501_41_dialog_content = "Oh? De que tipo de poder estamos falando?",
  ui_story_5023_50230501_42_dialog_content = "Err... Que tipo? Hum...",
  ui_story_5023_50230501_43_dialog_content = "Bem, certamente não é inteligência. Hmm... poderia ser poder carismático?",
  ui_story_5023_50230501_44_dialog_content = "Como você descobriu isso? Droga! A Bruxa Absolute Zero é ainda mais forte do que eu pensava...",
  ui_story_5023_50230501_45_dialog_content = "eu só... eu só <size=30>quero ser maduro e elegante como você...</size> ",
  ui_story_5023_50230501_46_dialog_content = "Huh? Eu não posso te ouvir.",
  ui_story_5023_50230501_47_dialog_content = "<size=45>Eu disse, quero me tornar madura e elegante assim como você!</size>",
  ui_story_5023_50230501_48_dialog_content = "Porque você é tão forte e tão bonita e sempre chama a atenção das pessoas sem precisar fazer nenhum truque...",
  ui_story_5023_50230501_49_dialog_content = "Ah! Nunca pensei que viveria para ver você me elogiar.",
  ui_story_5023_50230501_50_dialog_content = "É por isso que você roubou minhas roupas e meu chapéu?",
  ui_story_5023_50230501_51_dialog_content = "Sim... Mas eles são muito grandes para mim, eu não posso nem usá-los...",
  ui_story_5023_50230501_52_dialog_content = "Esta é uma operação fracassada, mas Zeta se tornará uma mulher madura e glamourosa um dia! Ainda melhor que você!",
  ui_story_5023_50230501_53_dialog_content = "Oh, você... aqui, sente-se aqui.",
  ui_story_5023_50230501_54_dialog_content = "Hã?",
  ui_story_5023_50230501_55_dialog_content = "As mulheres não são maduras e elegantes por causa da maneira como se vestem.",
  ui_story_5023_50230501_56_dialog_content = "Maquiagem e roupas são apenas ornamentos superficiais.",
  ui_story_5023_50230501_57_dialog_content = "Mas você sempre tem todos os meninos enrolados em seu dedo com sua aparência e seu corpo!",
  ui_story_5023_50230501_58_dialog_content = "Isso... Bem, eu não posso negar isso, mas vamos chamar isso de um hobby inofensivo meu.",
  ui_story_5023_50230501_59_dialog_content = "Eu não me importo que as pessoas comentem bem a minha figura.",
  ui_story_5023_50230501_60_dialog_content = "Mas eu ganho respeito com minha arma, carro, habilidades de combate e cérebro.",
  ui_story_5023_50230501_61_dialog_content = "Atenção e idolatria dos outros não importa. Você precisa se concentrar em fazer o que você é bom e o que você pode fazer.",
  ui_story_5023_50230501_62_dialog_content = "... Puxa, quando eu também comecei a dar palestras para as crianças...",
  ui_story_5023_50230501_63_dialog_content = "Zeta entende... mas também não.",
  ui_story_5023_50230501_64_dialog_content = "Que tipo de coisas posso fazer?",
  ui_story_5023_50230501_65_dialog_content = "Eu só sou bom para fazer aquelas pequenas tarefas básicas de patrulha que Regina e os outros não se dão ao trabalho de fazer...",
  ui_story_5023_50230501_66_dialog_content = "Não menospreze as tarefas servis que contribuem para ajudar os aldeões a expulsar os Eclipsitas.",
  ui_story_5023_50230501_67_dialog_content = "Eles são cruciais para desenvolver nosso relacionamento com todas as vilas e cidades do deserto.",
  ui_story_5023_50230501_68_dialog_content = "Eu choro toda vez que ajudo Roy cortei cebolas berry, e eu nem consigo cortá-las bem...",
  ui_story_5023_50230501_69_dialog_content = "Mas você o ajuda a garantir que todos os pratos estejam sempre saborosos, não é?",
  ui_story_5023_50230501_70_dialog_content = "Roy tem milhares de receitas na cabeça, mas seu paladar é péssimo. Sofreríamos muito sem você.",
  ui_story_5023_50230501_71_dialog_content = "Parece que existem algumas coisas que eu posso fazer muito bem depois de tudo! E posso fazer ainda melhor!",
  ui_story_5023_50230501_72_dialog_content = "Eu não sabia que você podia ser tão gentil e paciente...",
  ui_story_5023_50230501_73_dialog_content = "Tem algo que você esqueceu?",
  ui_story_5023_50230501_74_dialog_content = "Hã?",
  ui_story_5023_50230501_75_dialog_content = "O que há com essa pequena pegada de lama na minha jaqueta branca? Hum?",
  ui_story_5023_50230501_76_dialog_content = "Err... Isso...",
  ui_story_5023_50230501_77_dialog_content = "Lave-o novamente.",
  ui_story_5023_50230501_78_dialog_content = "N-Sem problemas! Meus amigos são muito bons em lavar roupas!",
  ui_story_5023_50230501_79_dialog_content = "Não basta encerrar o dia jogando-o em sua máquina e girando-o com seus Luminatics.",
  ui_story_5023_50230501_80_dialog_content = "Só lavar as mãos.",
  ui_story_5023_50230501_81_dialog_content = "Direita. Agora.",
  ui_story_5023_50230501_82_dialog_content = "*Sniff* As bruxas são assustadoras, afinal...",
  ui_story_5023_50230601_1_dialog_content = "Foi uma noite fria e escura como breu...",
  ui_story_5023_50230601_2_dialog_content = "Talvez porque o vento uivava sobre a areia...",
  ui_story_5023_50230601_3_dialog_content = "Ou talvez tenha sido o pensamento de perigos ocultos à espreita na noite que me deixou ansioso.",
  ui_story_5023_50230601_4_dialog_content = "Eu me mexi e me virei inquieta na cama, a insônia se recusando a me deixar cair no sono.",
  ui_story_5023_50230601_5_dialog_content = "De quem foi a ideia de contar histórias assustadoras perto da fogueira?",
  ui_story_5023_50230601_6_dialog_content = "Calma! Ouço!",
  ui_story_5023_50230601_7_dialog_content = "Assim como eu estava indo e voltando entre meus sonhos e o mundo desperto, ouvi uma voz.",
  ui_story_5023_50230601_8_dialog_content = "Era a voz de uma mulher, vindo do lado de fora do meu quarto. Parecia sussurros ao vento...",
  ui_story_5023_50230601_9_dialog_content = "No entanto, também parecia que estava bem ao meu lado, respirando no meu ouvido.",
  ui_story_5023_50230601_10_dialog_content = "Huh??",
  ui_story_5023_50230601_11_dialog_content = "Sentei-me imediatamente. E o que eu vi na tênue luz da lua...",
  ui_story_5023_50230601_12_dialog_content = "Pare! D-Não continue...",
  ui_story_5023_50230601_13_dialog_content = "...era Rouge, Bently and Lompty dormindo profundamente.",
  ui_story_5023_50230601_14_dialog_content = "... Que diabos?! Você chama isso de... Ai!",
  ui_story_5023_50230601_15_dialog_content = "não interrompa Ruby quando ela está lendo seu incrível épico, Great Explorer Ruby's Adventures!",
  ui_story_5023_50230601_16_dialog_content = "Minha adrenalina estava no auge.",
  ui_story_5023_50230601_17_dialog_content = "Porque de repente percebi que, embora pretendesse explorar todo o Astra...",
  ui_story_5023_50230601_18_dialog_content = "Eu nem tinha explorado este lugar – nossa terra natal!",
  ui_story_5023_50230601_19_dialog_content = "Este incidente assustador ocorreu no Oasis?! EU... Fleur, acordar! Acordar!",
  ui_story_5023_50230601_20_dialog_content = "Aaaaaaargh! Por que ele dorme como uma pessoa morta?!",
  ui_story_5023_50230601_21_dialog_content = "Ahem... Eu não me importo com histórias chatas como essa. Ainda não terminei o treino de hoje, então vou apenas...",
  ui_story_5023_50230601_22_dialog_content = "Nada de deixar no meio!",
  ui_story_5023_50230601_23_dialog_content = "Então decidi seguir meu coração e instintos de explorador...",
  ui_story_5023_50230601_24_dialog_content = "Saí imediatamente para ver o que essa nossa base familiar poderia estar escondendo.",
  ui_story_5023_50230601_25_dialog_content = "Ah, eu nem sabia que você passou por tudo isso!",
  ui_story_5023_50230601_26_dialog_content = "Parece que a partir de agora eu preciso manter um olho aberto durante o sono para fornecer melhor proteção a ela.",
  ui_story_5023_50230601_27_dialog_content = "Quando saí pela porta, a já escassa luz da lua foi obscurecida por nuvens escuras, envolvendo a noite em escuridão total.",
  ui_story_5023_50230601_28_dialog_content = "O vento, que uivava a noite toda, parou. Eu podia ouvir o som do meu próprio coração batendo na quietude mortal.",
  ui_story_5023_50230601_29_dialog_content = "Tum... Tum...",
  ui_story_5023_50230601_30_dialog_content = "E então de repente! Eu ouvi de novo!",
  ui_story_5023_50230601_31_dialog_content = "A voz estava murmurando algo, mas mal era destilável...",
  ui_story_5023_50230601_32_dialog_content = "Espere, isso é um erro de digitação. É suposto dizer \"mal discernível\"... De qualquer forma.",
  ui_story_5023_50230601_33_dialog_content = "Estava muito distante e quase imperceptível, eu não conseguia entender o que estava dizendo.",
  ui_story_5023_50230601_34_dialog_content = "Mas na ausência do vento, eu conseguia descobrir de onde vinha o som...",
  ui_story_5023_50230601_35_dialog_content = "Estava bem acima de mim! No entanto...",
  ui_story_5023_50230601_36_dialog_content = "O quarto acima de mim sempre esteve vazio!",
  ui_story_5023_50230601_37_dialog_content = "Ahh!",
  ui_story_5023_50230601_38_dialog_content = "Rangido!",
  ui_story_5023_50230601_39_dialog_content = "Achei que as histórias de Ruby eram suas favoritas, não seja covarde!",
  ui_story_5023_50230601_40_dialog_content = "Não foi a história, foi o seu grito! Assustou-me a luz do dia!",
  ui_story_5023_50230601_41_dialog_content = "Duas emoções estavam se chocando dentro de mim naquele momento.",
  ui_story_5023_50230601_42_dialog_content = "O medo do desconhecido enviou um calafrio na minha espinha. No entanto, um fluxo de adrenalina percorreu meu corpo como eletricidade, até meu cérebro!",
  ui_story_5023_50230601_43_dialog_content = "Mas a emoção de explorar o desconhecido logo suprimiu a inquietação em meu coração e me ajudou a manter a calma.",
  ui_story_5023_50230601_44_dialog_content = "Não hesitei e imediatamente comecei a subir as escadas.",
  ui_story_5023_50230601_45_dialog_content = "Ruby! Por favor, me acorde se isso acontecer de novo!",
  ui_story_5023_50230601_46_dialog_content = "Esse tipo de coisa é muito perigoso para você enfrentar sozinho!",
  ui_story_5023_50230601_47_dialog_content = "Parei do lado de fora da sala vazia por um longo momento.",
  ui_story_5023_50230601_48_dialog_content = "A porta normalmente trancada estava aberta apenas uma fresta, mas não havia luz lá dentro.",
  ui_story_5023_50230601_49_dialog_content = "Na abadia escura... aham.",
  ui_story_5023_50230601_50_dialog_content = "No abismo escuro, parecia que havia algo me observando.",
  ui_story_5023_50230601_51_dialog_content = "Por uma fração de segundo, eu queria apenas me virar e fugir. No entanto, o Sr. Jim de repente veio à minha mente.",
  ui_story_5023_50230601_52_dialog_content = "Meu ídolo, Sr. Jim, o lendário explorador, definitivamente superaria seu medo e entraria no quarto escuro para uma resposta!",
  ui_story_5023_50230601_53_dialog_content = "E assim, um fluxo quente de coragem encheu meu coração e dispersou meu medo.",
  ui_story_5023_50230601_54_dialog_content = "Coloquei uma mão na maçaneta e, quando estava prestes a entrar, ouvi a voz novamente.",
  ui_story_5023_50230601_55_dialog_content = "Desta vez, foi alto e claro—",
  ui_story_5023_50230601_56_dialog_content = "\"Obrigado por sua companhia todos esses anos. Mas ainda me sinto tão solitário às vezes...\"",
  ui_story_5023_50230601_57_dialog_content = "\"Há coisas que devo fazer.\"",
  ui_story_5023_50230601_58_dialog_content = "O... O que isso significava?",
  ui_story_5023_50230601_59_dialog_content = "Eu estava prestes a me aproximar quando ouvi o som de uma arma sendo carregada.",
  ui_story_5023_50230601_60_dialog_content = "Senti um desejo arrepiante de matar. Ele penetrou na escuridão e em meu corpo como uma adaga afiada.",
  ui_story_5023_50230601_61_dialog_content = "Eu me movi para trás passo a passo. Honestamente, não consigo me lembrar de como voltei para minha cama.",
  ui_story_5023_50230601_62_dialog_content = "Na manhã seguinte, corri para o quarto no andar de cima...",
  ui_story_5023_50230601_63_dialog_content = "Estava vazio.",
  ui_story_5023_50230601_64_dialog_content = "Ainda há muitas incógnitas neste mundo esperando para serem descobertas...",
  ui_story_5023_50230601_65_dialog_content = "Deve ter sido um fantasma! Eu sou positivo!",
  ui_story_5023_50230601_66_dialog_content = "Se você tivesse ficado lá mais um momento, aquela voz o teria arrastado para o mundo dos fantasmas!",
  ui_story_5023_50230601_67_dialog_content = "O mundo dos fantasmas? Isso é verdade, Ruby?",
  ui_story_5023_50230601_68_dialog_content = "Sinto muito, mas seu palpite é tão bom quanto o meu.",
  ui_story_5023_50230601_69_dialog_content = "Foi uma aventura mal sucedida. A verdade permanece escondida na densa neblina.",
  ui_story_5023_50230601_70_dialog_content = "Ainda tenho muito espaço para crescer e melhorar como explorador...",
  ui_story_5023_50230601_71_dialog_content = "Se existe um mundo de fantasmas, seria interessante. Vocês não acham?",
  ui_story_5023_50230601_72_dialog_content = "Sim! Estarei ao lado de Ruby não importa o que aconteça!",
  ui_story_5023_50230601_73_dialog_content = "Ranger!",
  ui_story_5023_50230601_74_dialog_content = "Posso sair agora...",
  ui_story_5023_50230601_75_dialog_content = "Atchim!",
  ui_story_5023_50230601_76_dialog_content = "Você está bem? Você precisa de uma jaqueta?",
  ui_story_5023_50230601_77_dialog_content = "Eu não estou com frio. Foi só um espirro aleatório...",
  ui_story_5023_50230601_78_dialog_content = "Eu diria que é porque alguém está fofocando sobre mim, mas você está falando de mim na minha frente, não nas minhas costas... então deve ser a poeira.",
  ui_story_5023_50230601_79_dialog_content = "Tem certeza de que não quer alguns dias de descanso antes de sair novamente?",
  ui_story_5023_50230601_80_dialog_content = "Eu mantive seu quarto intocado.",
  ui_story_5023_50230601_81_dialog_content = "Não há necessidade. Recebi uma mensagem de um contato do Courier Union referente a um lote de mercadorias que estava procurando.",
  ui_story_5023_50230601_82_dialog_content = "Tudo bem, então. Deixe-me saber se você precisa de backup.",
  ui_story_5023_50230601_83_dialog_content = "Azure, cuide-se. Olho do Lince, cuide dela.",
  ui_story_5023_50230601_84_dialog_content = "... Por que você está falando com minha arma?",
  ui_story_5023_50230601_85_dialog_content = "Hum? Você não fala com ele com frequência quando está sozinho?",
  ui_story_5023_50230601_86_dialog_content = "Eu estou fora. Tenho a sensação de que esta será uma viagem muito proveitosa.",
  ui_story_5023_50230601_87_dialog_content = "Isso seria perfeito, considerando quanto dinheiro sempre precisamos para reparos após o Blazing Rally...",
  ui_story_5023_50230601_88_dialog_content = "Caçada feliz."
}
return config
